def transform(grid):
    # Connect successive marked points in row-major order by orthogonal lines,
    # choosing horizontal first when the first point is above the next.
    out=[row[:] for row in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    # Connect points in row-major order, using the observed stair-step route:
    # from each point, align to the next row/column with a horizontal/vertical segment.
    for (r1,c1),(r2,c2) in zip(pts,pts[1:]):
        if r1==r2:
            for c in range(min(c1,c2)+1,max(c1,c2)): out[r1][c]=3
        elif c1==c2:
            for r in range(min(r1,r2)+1,max(r1,r2)): out[r][c1]=3
        else:
            # route toward the next point with an elbow; vertical then horizontal
            # according to line network inferred from demo.
            for r in range(min(r1,r2)+1,max(r1,r2)+1):
                if r!=r2: out[r][c1]=3
            # completion horizontal at r2
            for c in range(min(c1,c2)+1,max(c1,c2)):
                out[r2][c]=3
    return out
